content.arguments:
{"command":"$p=(Get-Item './').FullName
$bl=[IO.File]::ReadAllLines($p,[Text.Encoding]::UTF8)
for($i=0;$i -lt $bl.Count;$i++){
  $l=$bl[$i]
  if($l.StartsWith('|') -and $l.Length -gt 120){
    "LINE=$($i+1) LEN=$($l.Length)"
    "  " + $l.Substring(0,[Math]::Min(90,$l.Length)) + " ..."
  }
}","description":"列出超过 120 字的表格行"}

